#!/usr/bin/env node
/**
 * Generates CLAUDE.md from the canonical repository-wide AGENTS.md rules.
 *
 * Some agent hosts auto-load CLAUDE.md instead of AGENTS.md. Keeping a
 * generated byte-for-byte body prevents those hosts from receiving an older,
 * weaker policy while AGENTS.md remains the only editable source.
 */
const fs = require("node:fs");
const path = require("node:path");

const repoRoot = path.resolve(__dirname, "..", "..");
const sourcePath = path.join(repoRoot, "AGENTS.md");
const targetPath = path.join(repoRoot, "CLAUDE.md");

function renderClaudeRules(source) {
  if (!source.startsWith("# AGENTS\n")) {
    throw new Error("AGENTS.md must begin with the canonical '# AGENTS' heading");
  }
  return [
    "<!-- GENERATED FILE: edit AGENTS.md, then run node scripts/dev/generate-claude-rules.cjs. -->",
    "# CLAUDE",
    "",
    "> This compatibility copy is generated from `AGENTS.md`; `AGENTS.md` remains the only editable source.",
    source.slice("# AGENTS\n".length)
  ].join("\n");
}

function main() {
  const expected = renderClaudeRules(fs.readFileSync(sourcePath, "utf8"));
  if (process.argv.includes("--check")) {
    const actual = fs.existsSync(targetPath) ? fs.readFileSync(targetPath, "utf8") : "";
    if (actual !== expected) {
      throw new Error("CLAUDE.md is stale; regenerate it from AGENTS.md");
    }
    console.log("generate-claude-rules: OK");
    return;
  }
  fs.writeFileSync(targetPath, expected, "utf8");
  console.log("generate-claude-rules: wrote CLAUDE.md");
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(`generate-claude-rules: ${error.message}`);
    process.exitCode = 1;
  }
}

module.exports = { renderClaudeRules };
